// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}("");
        if (success) {
            uint256 toGive = c.value();
            if (toGive > 0) {
                assertTrue(c.blacklist(caller));
            }
        }
    }
}

